(7414593, 1169352, 114225, '<td valign="top">This texture is more distracting than anything.</td>', 'This texture is more distracting than anything.', '2015-11-06 13:18:28.000000', NULL, 1),
(7414594, 1169442, 114225, '<td valign="top">Classic texture with a classic setup. Nice.</td>', 'Classic texture with a classic setup. Nice.', '2015-11-06 13:18:52.000000', NULL, 1),
(7414595, 1169427, 114225, '<td valign="top">The photo is great. The texture applied doesn''t really add anything.</td>', 'The photo is great. The texture applied doesn''t really add anything.', '2015-11-06 13:19:50.000000', NULL, 1),
(7414596, 1169428, 114225, '<td valign="top">Less of a texture and more of a feature.</td>', 'Less of a texture and more of a feature.', '2015-11-06 13:20:26.000000', NULL, 1),
(7414597, 1169429, 114225, '<td valign="top">I don''t get what the building adds to this.</td>', 'I don''t get what the building adds to this.', '2015-11-06 13:22:11.000000', NULL, 1),
(7414598, 1169413, 114225, '<td valign="top">This seems more like you created a brand new scene, instead of enhancing the scene that is already there.</td>', 'This seems more like you created a brand new scene, instead of enhancing the scene that is already there.', '2015-11-06 13:23:29.000000', NULL, 1),
(7414599, 1169226, 114225, '<td valign="top">I really like what the wood texture does here.</td>', 'I really like what the wood texture does here.', '2015-11-06 13:24:27.000000', NULL, 1),
(7414600, 1169387, 114225, '<td valign="top">Great washed out look.</td>', 'Great washed out look.', '2015-11-06 13:24:38.000000', NULL, 1),
(7414604, 1169411, 159723, '<td valign="top">So good! (Commenting only)</td>', 'So good! (Commenting only)', '2015-11-06 13:59:46.000000', NULL, 1),
(7414626, 1169327, 114225, '<td valign="top">This is a photo that has to be admired for more than 2 seconds to really understand.</td>', 'This is a photo that has to be admired for more than 2 seconds to really understand.', '2015-11-06 14:56:38.000000', NULL, 1),
(7414627, 1169456, 114225, '<td valign="top">I like the heavy contrast. Maybe I could do without such a blown out sky, but it is somehow ok against the clipped blacks.</td>', 'I like the heavy contrast. Maybe I could do without such a blown out sky, but it is somehow ok against the clipped blacks.', '2015-11-06 14:57:12.000000', NULL, 1),
(7414628, 1169418, 114225, '<td valign="top">I like the use of blue here.</td>', 'I like the use of blue here.', '2015-11-06 14:57:26.000000', NULL, 1),
(7414629, 1169406, 114225, '<td valign="top">Classic portrait for a texture. But almost fully hiding an eye hurts.</td>', 'Classic portrait for a texture. But almost fully hiding an eye hurts.', '2015-11-06 14:57:56.000000', NULL, 1),
(7414630, 1169424, 114225, '<td valign="top">Interesting use of texture, creates more of a different scene, while letting the original scene show through.</td>', 'Interesting use of texture, creates more of a different scene, while letting the original scene show through.', '2015-11-06 14:58:20.000000', NULL, 1),
(7414631, 1169416, 114225, '<td valign="top">I''ve probably spent more time trying to understand if this is vertical or horizontal than I have looking at the contents of the photo.</td>', 'I''ve probably spent more time trying to understand if this is vertical or horizontal than I have looking at the contents of the photo.', '2015-11-06 14:58:54.000000', NULL, 1),
(7414632, 1169284, 114225, '<td valign="top">This works well. Almost a double exposure feel, but not quite.</td>', 'This works well. Almost a double exposure feel, but not quite.', '2015-11-06 14:59:09.000000', NULL, 1),
(7414633, 1169392, 114225, '<td valign="top">I like how the little texture here is used to enhance.</td>', 'I like how the little texture here is used to enhance.', '2015-11-06 14:59:23.000000', NULL, 1),
(7414634, 1169348, 114225, '<td valign="top">Good setup for a grunge texture. I kind of find how the eyes are looking away as a distraction.</td>', 'Good setup for a grunge texture. I kind of find how the eyes are looking away as a distraction.', '2015-11-06 14:59:59.000000', NULL, 1),
(7414635, 1169269, 114225, '<td valign="top">Simple yet elegant.</td>', 'Simple yet elegant.', '2015-11-06 15:00:11.000000', NULL, 1),
(7414636, 1169326, 114225, '<td valign="top">Nice color to evoke emotion.</td>', 'Nice color to evoke emotion.', '2015-11-06 15:00:26.000000', NULL, 1),
(7414637, 1169412, 114225, '<td valign="top">I''m not certain what is going on here. The main subject is what, a garbage bag? I just don''t know.</td>', 'I''m not certain what is going on here. The main subject is what, a garbage bag? I just don''t know.', '2015-11-06 15:00:55.000000', NULL, 1),
(7414638, 1169449, 114225, '<td valign="top">Seems like you have some odd grey spots. Not sure you picked the best blending mode.</td>', 'Seems like you have some odd grey spots. Not sure you picked the best blending mode.', '2015-11-06 15:01:16.000000', NULL, 1),
(7414639, 1169438, 114225, '<td valign="top">The texture here plays such a little role that it''s basically inconsequential.</td>', 'The texture here plays such a little role that it''s basically inconsequential.', '2015-11-06 15:40:37.000000', NULL, 1),
(7414640, 1169001, 114225, '<td valign="top">Not sure I get the texture here. Doesn''t seem to fit the subject.</td>', 'Not sure I get the texture here. Doesn''t seem to fit the subject.', '2015-11-06 15:41:03.000000', NULL, 1),
(7414641, 1169444, 114225, '<td valign="top">That glow on the label is extremly distracting.</td>', 'That glow on the label is extremly distracting.', '2015-11-06 15:41:21.000000', NULL, 1),
(7414642, 1169454, 114225, '<td valign="top">Feels more like an odd double exposure than a real texture.</td>', 'Feels more like an odd double exposure than a real texture.', '2015-11-06 15:41:44.000000', NULL, 1),
(7414643, 1169411, 114225, '<td valign="top">Something about this isn''t jibing with me. IT just feels uneven.</td>', 'Something about this isn''t jibing with me. IT just feels uneven.', '2015-11-06 15:42:16.000000', NULL, 1),
(7414644, 1169285, 114225, '<td valign="top">The texture here seems to get in the way more than enhance.</td>', 'The texture here seems to get in the way more than enhance.', '2015-11-06 15:42:35.000000', NULL, 1),
(7414645, 1169430, 114225, '<td valign="top">The dark triangle is a major distraction.</td>', 'The dark triangle is a major distraction.', '2015-11-06 15:42:56.000000', NULL, 1),
