(7414648, 1169431, 114225, '<td valign="top">I guess if I look close, I can see a texture. But then I see that it''s a distracting element.</td>', 'I guess if I look close, I can see a texture. But then I see that it''s a distracting element.', '2015-11-06 15:44:20.000000', NULL, 1),
(7414649, 1169414, 114225, '<td valign="top">Those things in the lower right are very distracting.</td>', 'Those things in the lower right are very distracting.', '2015-11-06 15:44:55.000000', NULL, 1),
