(7414655, 1169287, 114225, '<td valign="top">The base photo being out of focus cannot be helped with the texture, I''m afraid.</td>', 'The base photo being out of focus cannot be helped with the texture, I''m afraid.', '2015-11-06 15:47:27.000000', NULL, 1),
