(7415336, 1169462, 40391, '<td valign="top">Like an angora shawl. Beautiful.</td>', 'Like an angora shawl. Beautiful.', '2015-11-10 07:27:04.000000', NULL, 1),
(7415337, 1169269, 40391, '<td valign="top">Beautiful minimalism.</td>', 'Beautiful minimalism.', '2015-11-10 07:27:28.000000', NULL, 1),
(7415338, 1169352, 40391, '<td valign="top">Quite interesting and enjoyable to view.</td>', 'Quite interesting and enjoyable to view.', '2015-11-10 07:30:25.000000', NULL, 1),
(7415340, 1169392, 40391, '<td valign="top">Dreamy.</td>', 'Dreamy.', '2015-11-10 07:32:18.000000', NULL, 1),
(7415401, 1169284, 23484, '<td valign="top">Very well done. I love that.</td>', 'Very well done. I love that.', '2015-11-10 17:02:17.000000', NULL, 1),
(7415402, 1169387, 23484, '<td valign="top">Gorgeous job. The overlay works very well.</td>', 'Gorgeous job. The overlay works very well.', '2015-11-10 17:02:36.000000', NULL, 1),
(7415403, 1169456, 23484, '<td valign="top">Very cool silhouette.</td>', 'Very cool silhouette.', '2015-11-10 17:02:58.000000', NULL, 1),
