(7415405, 1169406, 120058, '<td valign="top">Amazing picture! 10</td>', 'Amazing picture! 10', '2015-11-10 17:06:36.000000', NULL, 1),
(7415406, 1169442, 120058, '<td valign="top">I absolutely love this! Top 5 for me, gave it a 10. Seems like many people misunderstood the challenge and made "double exposures" instead, but this is an amazing use of texture overlay. It''s like looking at a photo of a canvas!</td>', 'I absolutely love this! Top 5 for me, gave it a 10. Seems like many people misunderstood the challenge and made "double exposures" instead, but this is an amazing use of texture overlay. It''s like looking at a photo of a canvas!', '2015-11-10 17:06:45.000000', NULL, 1),
(7415407, 1169348, 120058, '<td valign="top">I love the vingage look you achieved with the texture overlay! Top 5!</td>', 'I love the vingage look you achieved with the texture overlay! Top 5!', '2015-11-10 17:07:07.000000', NULL, 1),
(7415408, 1169326, 120058, '<td valign="top">Scary, actually better than some of the pictures in the Halloween challenge ^^ Top 5 for me.</td>', 'Scary, actually better than some of the pictures in the Halloween challenge ^^ Top 5 for me.', '2015-11-10 17:07:39.000000', NULL, 1),
(7415409, 1169462, 120058, '<td valign="top">It took me a bit of getting used to this, but after looking at it several times I''ve decided that I really like it. Top 10 for me!</td>', 'It took me a bit of getting used to this, but after looking at it several times I''ve decided that I really like it. Top 10 for me!', '2015-11-10 17:08:19.000000', NULL, 1),
(7415416, 1169269, 19825, '<td valign="top">Now see, this is an effective use of texture. As in, I wish my entry looked this good.</td>', 'Now see, this is an effective use of texture. As in, I wish my entry looked this good.', '2015-11-10 17:43:45.000000', NULL, 1),
(7415417, 1169284, 19825, '<td valign="top">OK, I am not sure this is what the challenge theme had in mind. That said, I am not a stickler for strict interpretation of the theme. I''ll take an interesting image roughly inspired by the challenge theme over a ho-hum image that strictly fits the theme any day. I like this.</td>', 'OK, I am not sure this is what the challenge theme had in mind. That said, I am not a stickler for strict interpretation of the theme. I''ll take an interesting image roughly inspired by the challenge theme over a ho-hum image that strictly fits the theme any day. I like this.', '2015-11-10 17:53:33.000000', NULL, 1),
(7415418, 1169442, 19825, '<td valign="top">Lovely color palette and light. I worry some will find the texture too subtle -- I hope not. This is very nice.</td>', 'Lovely color palette and light. I worry some will find the texture too subtle -- I hope not. This is very nice.', '2015-11-10 17:54:46.000000', NULL, 1),
(7415419, 1169430, 19825, '<td valign="top">I think the added texture compliments this nicely.</td>', 'I think the added texture compliments this nicely.', '2015-11-10 17:55:23.000000', NULL, 1),
(7415420, 1169438, 19825, '<td valign="top">One of those images I find pleasing, but I am not sure how to articulate why. Gosh, that was helpful, wasn''t it?</td>', 'One of those images I find pleasing, but I am not sure how to articulate why. Gosh, that was helpful, wasn''t it?', '2015-11-10 17:56:25.000000', NULL, 1),
(7415421, 1169199, 19825, '<td valign="top">Personally, I am not sure how much the texture adds to this, but I like the image -- the colors and composition especially.</td>', 'Personally, I am not sure how much the texture adds to this, but I like the image -- the colors and composition especially.', '2015-11-10 17:57:40.000000', NULL, 1),
(7415422, 1169427, 19825, '<td valign="top">I am a sucker for a good kid picture. The texture is subtle, but I think that was a good choice.</td>', 'I am a sucker for a good kid picture. The texture is subtle, but I think that was a good choice.', '2015-11-10 17:58:29.000000', NULL, 1),
(7415423, 1169226, 19825, '<td valign="top">Nice paring of primary image and texture.</td>', 'Nice paring of primary image and texture.', '2015-11-10 17:59:35.000000', NULL, 1),
(7415500, 1169406, 94815, '<td valign="top">Have you tried this upside down? Seems to work both ways.</td>', 'Have you tried this upside down? Seems to work both ways.', '2015-11-10 21:54:24.000000', NULL, 1),
(7415501, 1169428, 94815, '<td valign="top">I like the idea.</td>', 'I like the idea.', '2015-11-10 21:56:14.000000', NULL, 1),
