(7416043, 1169462, 115814, '<td valign="top">Absolutely  stunning. A clear standout for me in thes challenge - or better yet, a standout  as a singular photo, regardless of theme.</td>', 'Absolutely  stunning. A clear standout for me in thes challenge - or better yet, a standout  as a singular photo, regardless of theme.', '2015-11-13 09:03:21.000000', NULL, 0),
